// LÖVE + Lua autocompletion for CodeMirror.
//
// Function and method names come from love-api.json, which is generated by
// introspecting the real engine (tools/introspect.lua). Signatures and short
// docs come from love-docs.js.

import { CALLBACKS, DOCS, RETURNS, NAME_HINTS, METHOD_DOCS } from './love-docs.js';
import { SMITTEN_MODULES, LOVE_ADDITIONS, PATH_ARGS } from './smitten-docs.js';
import { SCRIPT_API, SCRIPT_CALLBACKS } from './core/script-api.js';
import { getSchema } from './core/schema.js';

const LUA_KEYWORDS = ['and', 'break', 'do', 'else', 'elseif', 'end', 'false', 'for', 'function', 'if', 'in', 'local', 'nil', 'not', 'or', 'repeat', 'return', 'then', 'true', 'until', 'while'];

const LUA_GLOBALS = {
  print: ['...', 'Prints to the console.'],
  pairs: ['t', 'Iterates over all key/value pairs.'],
  ipairs: ['t', 'Iterates over t[1], t[2], ... until nil.'],
  type: ['v', 'Returns the type name of a value.'],
  tostring: ['v', 'Converts a value to a string.'],
  tonumber: ['v, base?', 'Converts a value to a number, or nil.'],
  require: ['modname', 'Loads a module (e.g. require("player") loads player.lua).'],
  setmetatable: ['t, mt', 'Sets the metatable of a table.'],
  getmetatable: ['t', 'Returns the metatable of a value.'],
  error: ['message, level?', 'Raises an error.'],
  assert: ['v, message?', 'Raises an error if v is false or nil.'],
  pcall: ['f, ...', 'Calls f in protected mode; returns ok, results...'],
  xpcall: ['f, handler', 'Calls f with an error handler.'],
  select: ['n, ...', 'Returns arguments after n, or "#" for the count.'],
  unpack: ['t, i?, j?', 'Returns the elements of a table.'],
  rawget: ['t, k', 'Gets without metamethods.'],
  rawset: ['t, k, v', 'Sets without metamethods.'],
  rawequal: ['a, b', 'Compares without metamethods.'],
  next: ['t, k?', 'Next key/value pair in a table.'],
  loadstring: ['code, name?', 'Compiles a string into a function.'],
  collectgarbage: ['opt?, arg?', 'Controls the garbage collector.'],
  setfenv: ['f, t', 'Sets the environment of a function.'],
  getfenv: ['f?', 'Returns the environment of a function.'],
  _G: null, _VERSION: null, love: null, smitten: null, math: null, string: null, table: null, os: null, coroutine: null, utf8: null, io: null, debug: null, self: null,
};

const LUA_LIBS = {
  math: ['abs', 'acos', 'asin', 'atan', 'atan2', 'ceil', 'cos', 'cosh', 'deg', 'exp', 'floor', 'fmod', 'frexp', 'huge', 'ldexp', 'log', 'log10', 'max', 'min', 'modf', 'pi', 'pow', 'rad', 'random', 'randomseed', 'sin', 'sinh', 'sqrt', 'tan', 'tanh'],
  string: ['byte', 'char', 'dump', 'find', 'format', 'gmatch', 'gsub', 'len', 'lower', 'match', 'rep', 'reverse', 'sub', 'upper'],
  table: ['concat', 'insert', 'maxn', 'remove', 'sort'],
  os: ['clock', 'date', 'difftime', 'getenv', 'time'],
  coroutine: ['create', 'resume', 'running', 'status', 'wrap', 'yield'],
  utf8: ['char', 'charpattern', 'codepoint', 'codes', 'len', 'offset'],
  io: ['write', 'read', 'lines', 'open'],
  debug: ['traceback', 'getinfo', 'getlocal', 'sethook', 'gethook', 'getregistry'],
};

const METHOD_RETURNS = {
  getShape: 'Shape', getShapes: null, getBody: 'Body', getWorld: 'World', getFont: 'Font', getTexture: 'Texture',
  getCanvas: 'Texture', clone: null, getChannel: 'Channel', newImageData: 'ImageData',
};

const FILE_FUNCS = /(?:newImage|newSource|newFont|newShader|newImageData|newSoundData|newVideo|newImageFont|newArrayImage|newCubeImage|newDecoder|newFileData|read|lines|load|getInfo|newFile|openFile)\s*\(\s*["']([^"']*)$/;
const REQUIRE = /\brequire\s*\(?\s*["']([^"']*)$/;

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const visible = (name) => !name.startsWith('_');

export function createLoveCompletions(api, cm, getProjectFiles = () => []) {
  const { snippetCompletion } = cm.autocomplete;
  const { syntaxTree } = cm.language;
  const modules = api?.modules || {};
  const types = api?.types || {};
  const callbackNames = new Set(CALLBACKS.map((c) => c[0]));

  const fnOption = (mod, name) => {
    const d = DOCS[`${mod}.${name}`];
    return { label: name, type: 'function', detail: d ? `(${d[0]})` : undefined, info: d?.[1], boost: d ? 1 : 0 };
  };

  const moduleFns = {};
  for (const [mod, fns] of Object.entries(modules)) moduleFns[mod] = fns.filter(visible).map((f) => fnOption(mod, f));

  const loveMembers = [
    ...Object.keys(modules).map((m) => ({ label: m, type: 'namespace', detail: 'module', boost: 2 })),
    ...CALLBACKS.map(([name, args, doc]) => ({ label: name, type: 'method', detail: `callback (${args})`, info: doc })),
    ...(api?.love || []).filter((n) => visible(n) && !callbackNames.has(n) && !['boot', 'init', 'createhandlers', 'run', 'errhand'].includes(n))
      .map((n) => ({ label: n, type: 'function', detail: n === 'getVersion' ? '()' : undefined })),
  ];

  const callbackSnippets = CALLBACKS.map(([name, args, doc]) => snippetCompletion(
    `love.${name}(${args})\n\t\${}\nend`,
    { label: `love.${name}`, type: 'function', detail: `(${args})`, info: doc },
  ));

  // smitten is love: LÖVE's modules plus Smitten's, and helpers that join
  // LÖVE's modules (smitten-docs.js).
  const fnOpt = (name, d, detail) => (d
    ? { label: name, type: 'function', detail: `(${d[0]})`, info: d[1], boost: 1 }
    : { label: name, type: 'property', detail });
  const smittenModuleMembers = Object.fromEntries(Object.entries(SMITTEN_MODULES)
    .map(([mod, members]) => [mod, Object.entries(members).map(([n, d]) => fnOpt(n, d, `smitten.${mod}`))]));
  for (const [mod, members] of Object.entries(LOVE_ADDITIONS)) {
    moduleFns[mod] = [...(moduleFns[mod] || []), ...Object.entries(members).map(([n, d]) => fnOpt(n, d, `smitten.${mod}`))];
  }
  const engineMembers = [
    ...loveMembers,
    ...Object.keys(SMITTEN_MODULES).map((m) => ({ label: m, type: 'namespace', detail: 'module', boost: 2 })),
    { label: 'version', type: 'property', detail: 'Smitten\'s version' },
  ];
  const callbackSnippetsFor = (ns) => CALLBACKS.map(([name, args, doc]) => snippetCompletion(
    `${ns}.${name}(${args})\n\t\${}\nend`,
    { label: `${ns}.${name}`, type: 'function', detail: `(${args})`, info: doc },
  ));

  // Pieces: self:method() and the functions a script can define.
  const schema = (() => { try { return getSchema(); } catch { return { types: {} }; } })();
  const nodeMethodMap = new Map();
  const scriptEvents = new Map();
  for (const [type, def] of Object.entries(schema.types)) {
    for (const [m, d] of Object.entries(def.methods || {})) if (!nodeMethodMap.has(m)) nodeMethodMap.set(m, { label: m, type: 'method', detail: `(${d.args})`, info: `${type}: ${d.doc}`, boost: 1 });
    for (const [e, d] of Object.entries(def.events || {})) if (!scriptEvents.has(e)) scriptEvents.set(e, { name: e, args: d.args, doc: d.doc, type });
  }
  const nodeMethods = [...nodeMethodMap.values()];
  const eventSnippets = (cls) => [...scriptEvents.values()].map((e) => snippetCompletion(
    `${e.name}(${e.args === '' ? '' : e.args})\n\t\${}\nend`,
    { label: e.name, type: 'method', detail: `(${e.args})`, info: `${e.type}: ${e.doc}`, boost: 2 },
  ));

  const typeMethods = {};
  const allMethods = new Map(); // method -> [types]
  for (const [type, methods] of Object.entries(types)) {
    typeMethods[type] = methods.filter(visible).map((m) => {
      const d = METHOD_DOCS[`${type}:${m}`];
      if (!allMethods.has(m)) allMethods.set(m, []);
      allMethods.get(m).push(type);
      return { label: m, type: 'method', detail: d ? `(${d[0]})` : undefined, info: d ? d[1] : `${type}:${m}`, boost: d ? 1 : 0 };
    });
  }
  for (const s of LUA_LIBS.string) {
    if (!allMethods.has(s)) allMethods.set(s, []);
    allMethods.get(s).push('string');
  }
  const unionMethods = [...allMethods].map(([m, ts]) => ({
    label: m, type: 'method', detail: ts.length > 3 ? `${ts.slice(0, 3).join(', ')}, …` : ts.join(', '),
  }));

  const libMembers = {};
  for (const [lib, names] of Object.entries(LUA_LIBS)) {
    libMembers[lib] = names.map((n) => ({ label: n, type: ['pi', 'huge', 'charpattern'].includes(n) ? 'constant' : 'function', detail: lib }));
  }

  const keywordOptions = [
    ...LUA_KEYWORDS.map((k) => ({ label: k, type: 'keyword', boost: -1 })),
    snippetCompletion('function ${name}(${})\n\t${}\nend', { label: 'function', detail: 'snippet', type: 'keyword' }),
    snippetCompletion('local function ${name}(${})\n\t${}\nend', { label: 'local function', detail: 'snippet', type: 'keyword' }),
    snippetCompletion('for ${i} = 1, ${n} do\n\t${}\nend', { label: 'for', detail: 'numeric loop', type: 'keyword' }),
    snippetCompletion('for ${k}, ${v} in pairs(${t}) do\n\t${}\nend', { label: 'for pairs', detail: 'loop', type: 'keyword' }),
    snippetCompletion('for ${i}, ${v} in ipairs(${t}) do\n\t${}\nend', { label: 'for ipairs', detail: 'loop', type: 'keyword' }),
    snippetCompletion('if ${condition} then\n\t${}\nend', { label: 'if', detail: 'snippet', type: 'keyword' }),
    snippetCompletion('while ${condition} do\n\t${}\nend', { label: 'while', detail: 'snippet', type: 'keyword' }),
  ];
  // A script is the piece: its methods (move(), onGround()...), the short API
  // (pressed, spawn, sfx, wait...) and the callbacks it can define.
  const scriptApiOptions = SCRIPT_API.map(([name, sig, doc]) => ({
    label: name, type: 'function', detail: sig.slice(name.length), info: doc, boost: 2,
  }));
  const callbackOptions = SCRIPT_CALLBACKS.map((name) => {
    const e = scriptEvents.get(name);
    const args = e ? e.args : (name === 'update' || name === 'physicsUpdate' ? 'dt' : '');
    return snippetCompletion(`function ${name}(${args})\n\t\${}\nend`, {
      label: `function ${name}`, type: 'keyword', detail: `(${args})`, info: e ? `${e.type}: ${e.doc}` : 'Called by Smitten.', boost: 1,
    });
  });
  const globalOptions = Object.entries(LUA_GLOBALS).map(([name, d]) => ({
    label: name, type: d ? 'function' : (LUA_LIBS[name] || name === 'love' || name === 'smitten' ? 'namespace' : 'variable'),
    detail: d ? `(${d[0]})` : undefined, info: d?.[1], boost: name === 'love' || name === 'smitten' ? 3 : 0,
  }));

  function inferType(text, receiver) {
    const last = receiver.split(/[.:]/).pop();
    const patterns = [
      new RegExp(`(?:^|[^\\w.])${escapeRe(receiver)}\\s*=\\s*(?:love|smitten)\\.(\\w+)\\.(\\w+)`, 'm'),
      new RegExp(`(?:^|[^\\w])(?:[\\w.]+\\.)?${escapeRe(last)}\\s*=\\s*(?:love|smitten)\\.(\\w+)\\.(\\w+)`, 'm'),
    ];
    for (const re of patterns) {
      const m = re.exec(text);
      if (m && RETURNS[`${m[1]}.${m[2]}`]) return RETURNS[`${m[1]}.${m[2]}`];
    }
    const mr = new RegExp(`(?:^|[^\\w])(?:[\\w.]+\\.)?${escapeRe(last)}\\s*=\\s*[\\w.]+:(\\w+)\\s*\\(`, 'm').exec(text);
    if (mr && METHOD_RETURNS[mr[1]]) return METHOD_RETURNS[mr[1]];
    for (const [re, type] of NAME_HINTS) if (re.test(last)) return type;
    return null;
  }

  function projectFileOptions(prefix) {
    return getProjectFiles().filter((p) => !p.endsWith('/')).map((p) => ({ label: p, type: 'text', detail: 'file' }));
  }

  function requireOptions() {
    return getProjectFiles().filter((p) => p.endsWith('.lua') && p !== 'main.lua' && p !== 'conf.lua').map((p) => ({
      label: p.slice(0, -4).replace(/\/init$/, '').replace(/\//g, '.'), type: 'variable', detail: p,
    }));
  }

  /** Project files a path argument accepts. */
  function pathOptions(ext) {
    return getProjectFiles().filter((p) => ext.test(p)).map((p) => ({ label: p, type: 'text', detail: 'file' }));
  }

  function documentWords(state, current) {
    const words = new Set();
    const text = state.doc.toString();
    const re = /[A-Za-z_][\w]{2,}/g;
    let m;
    while ((m = re.exec(text)) && words.size < 2000) words.add(m[0]);
    words.delete(current);
    for (const k of LUA_KEYWORDS) words.delete(k);
    for (const g of Object.keys(LUA_GLOBALS)) words.delete(g);
    return [...words].map((w) => ({ label: w, type: 'text', boost: -2 }));
  }

  return function loveCompletionSource(context) {
    const { state, pos } = context;
    const line = state.doc.lineAt(pos);
    const before = line.text.slice(0, pos - line.from);
    const node = syntaxTree(state).resolveInner(pos, -1);
    const nodeName = node.name || '';
    let m;

    if (/string/i.test(nodeName) || /["'][^"']*$/.test(before)) {
      if ((m = REQUIRE.exec(before))) return { from: pos - m[1].length, options: requireOptions(), validFor: /^[\w.]*$/ };
      for (const arg of PATH_ARGS) {
        if ((m = arg.re.exec(before))) return { from: pos - m[1].length, options: pathOptions(arg.ext), validFor: /^[\w./-]*$/ };
      }
      if ((m = FILE_FUNCS.exec(before))) return { from: pos - m[1].length, options: projectFileOptions(m[1]), validFor: /^[\w./-]*$/ };
      if (/string/i.test(nodeName)) return null;
    }
    if (/comment/i.test(nodeName)) return null;

    if ((m = /\bfunction\s+((?:love|smitten)\.\w*)$/.exec(before))) {
      const ns = m[1].startsWith('smitten') ? 'smitten' : 'love';
      return { from: pos - m[1].length, options: callbackSnippetsFor(ns), validFor: /^\w+\.\w*$/ };
    }
    if ((m = /\bfunction\s+[A-Za-z_]\w*:(\w*)$/.exec(before))) {
      return { from: pos - m[1].length, options: eventSnippets(), validFor: /^\w*$/ };
    }
    if ((m = /(?:^|[^\w.:])(?:love|smitten)\.(\w+)\.(\w*)$/.exec(before))) {
      const opts = smittenModuleMembers[m[1]] || moduleFns[m[1]];
      return opts ? { from: pos - m[2].length, options: opts, validFor: /^\w*$/ } : null;
    }
    if ((m = /(?:^|[^\w.:])(?:love|smitten)\.(\w*)$/.exec(before))) {
      return { from: pos - m[1].length, options: engineMembers, validFor: /^\w*$/ };
    }
    if ((m = /\bself:(\w*)$/.exec(before))) {
      return { from: pos - m[1].length, options: nodeMethods, validFor: /^\w*$/ };
    }
    if ((m = /(?:^|[^\w.:])(math|string|table|os|coroutine|utf8|io|debug)\.(\w*)$/.exec(before))) {
      return { from: pos - m[2].length, options: libMembers[m[1]], validFor: /^\w*$/ };
    }
    if ((m = /([A-Za-z_][\w.]*|\))\s*:(\w*)$/.exec(before))) {
      const type = m[1] === ')' ? null : inferType(state.doc.toString(), m[1]);
      let options = type && typeMethods[type];
      if (type === 'Joint') options = typeMethods.Joint;
      return { from: pos - m[2].length, options: options || unionMethods, validFor: /^\w*$/ };
    }
    if ((m = /(?:^|[^\w.:])([A-Za-z_]\w*)$/.exec(before))) {
      return { from: pos - m[1].length, options: [...keywordOptions, ...callbackOptions, ...scriptApiOptions, ...nodeMethods, ...globalOptions, ...documentWords(state, m[1])], validFor: /^\w*$/ };
    }
    if (context.explicit) return { from: pos, options: [...globalOptions, ...keywordOptions] };
    return null;
  };
}
